CREATE DEFINER=`root`@`localhost` PROCEDURE `AddQty`(
    IN _date DATETIME,
    IN _code VARCHAR(255),
    IN _qty INT
)
BEGIN
    -- Insert the quantity change record into tblqty
    INSERT INTO tblqty (`date`, `code`, qty) 
    VALUES (_date, _code, _qty);

    -- Update the qty of tblproduct by adding _qty based on _code
    UPDATE tblproduct
    SET qty = qty + _qty
    WHERE `code` = _code;
END ;;
