CREATE DEFINER=`root`@`localhost` PROCEDURE `AddTemp`(
    IN _code VARCHAR(255),
    IN _date DATETIME,
    IN _quantity INT
)
BEGIN
    -- Check if the code already exists in tbltemp
    IF EXISTS (SELECT 1 FROM tbltemp WHERE `code` = _code) THEN
        -- If it exists, update the quantity by adding the new quantity
        UPDATE tbltemp
        SET `quantity` = `quantity` + _quantity
        WHERE `code` = _code;
    ELSE
        -- If it doesn't exist, insert a new record
        INSERT INTO tbltemp (
            `code`,
            `date`,
            `quantity`
        )
        VALUES (
            _code,
            _date,
            _quantity
        );
    END IF;
END ;;
DELIMITER ;
