CREATE DEFINER=`root`@`localhost` PROCEDURE `GetMonthlySales`()
BEGIN
 SELECT 
        MONTH(t.date) AS `month`,
        SUM(p.price * t.quantity) AS total_sales
    FROM 
        tblpurchase t
    INNER JOIN 
        tblproduct p 
        ON p.code = t.code
    WHERE 
        YEAR(t.date) = YEAR(CURDATE())
    GROUP BY 
        MONTH(t.date)
    ORDER BY 
        MONTH(t.date);
END ;;
DELIMITER ;
