DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SearchProduct`(
    IN search VARCHAR(255)
)
BEGIN
    SET @searchWildcard = CONCAT('%', search, '%');

    SELECT 
        p.*, 
        COALESCE(SUMQ.total_qty, 0) AS qty,
        CASE 
            WHEN COALESCE(SUMQ.total_qty, 0) = 0 THEN 'Out of Stock'
            ELSE 'Available'
        END AS status
    FROM tblproduct p
    LEFT JOIN (
        SELECT code, SUM(qty) AS total_qty
        FROM tblqty
        GROUP BY code
    ) AS SUMQ ON p.code = SUMQ.code
    WHERE
        p.code = search OR
        p.name LIKE @searchWildcard OR
        p.price = search;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
