CREATE DEFINER=`root`@`localhost` PROCEDURE `SearchUser`(
    IN search VARCHAR(255)
)
BEGIN
    SET @searchWildcard = CONCAT('%', search, '%');
    SELECT * FROM tblusers
			 WHERE
	   `userID` = search OR
       `name` LIKE @searchWildcard OR
       `username` = @searchWildcard OR
       `role` = @search;
END ;;
