/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `TempToPurchase`()
BEGIN
  SET SQL_SAFE_UPDATES = 0;

  -- Insert data from tbltemp to tblpurchase
  INSERT INTO tblpurchase (`date`, `code`, quantity)
  SELECT `date`, `code`, quantity
  FROM tbltemp;

  -- Subtract the quantity from tblproduct instead of tblqty
  UPDATE tblproduct p
  JOIN (
      SELECT code, SUM(quantity) AS total_quantity
      FROM tbltemp
      GROUP BY code
  ) t ON p.code = t.code
  SET p.qty = p.qty - t.total_quantity;

  -- Delete all records from tbltemp
  DELETE FROM tbltemp;

  SET SQL_SAFE_UPDATES = 1;

  -- Return 1 indicating success
  SELECT 1 AS success;
END ;;
DELIMITER ;
