CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdateProduct`(
    IN _productID INT,
	IN _photo LONGBLOB,
     IN _code VARCHAR(255),
    IN _name VARCHAR(255),
    IN _price DOUBLE
)
BEGIN
